package com.medicine.reminder.service;
import com.medicine.reminder.dto.ReminderDTO; import com.medicine.reminder.model.*; import com.medicine.reminder.repository.*; import org.springframework.http.HttpStatus; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class ReminderService {private final ReminderRepository reminders;private final MedicineRepository meds;private final HistoryService history;public ReminderService(ReminderRepository r,MedicineRepository m,HistoryService h){reminders=r;meds=m;history=h;}
 public List<Reminder> list(Long medicineId,Long uid){ownedMedicine(medicineId,uid);return reminders.findByMedicineIdOrderByTimeAsc(medicineId);} public Reminder create(ReminderDTO d,Long uid){Reminder r=new Reminder();copy(r,d);r.setMedicine(ownedMedicine(d.getMedicineId(),uid));return reminders.save(r);} public Reminder update(Long id,ReminderDTO d,Long uid){Reminder r=owned(id,uid);copy(r,d);if(!r.getMedicine().getId().equals(d.getMedicineId()))r.setMedicine(ownedMedicine(d.getMedicineId(),uid));return reminders.save(r);} public void delete(Long id,Long uid){reminders.delete(owned(id,uid));}
 private void copy(Reminder r,ReminderDTO d){r.setTime(d.getTime());r.setFrequency(d.getFrequency().toUpperCase());r.setDaysOfWeek(d.getDaysOfWeek());r.setStartDate(d.getStartDate());r.setEndDate(d.getEndDate());if(d.getIsActive()!=null)r.setIsActive(d.getIsActive());} private Medicine ownedMedicine(Long id,Long uid){return meds.findByIdAndProfileUserId(id,uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Medicine not found"));} private Reminder owned(Long id,Long uid){return reminders.findByIdAndMedicineProfileUserId(id,uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Reminder not found"));}
 @Scheduled(fixedRate=60000) public void markMissedReminders(){LocalDate today=LocalDate.now();String day=today.getDayOfWeek().name().substring(0,3);for(Reminder r:reminders.findByIsActiveTrue()){if((r.getStartDate()!=null&&today.isBefore(r.getStartDate()))||(r.getEndDate()!=null&&today.isAfter(r.getEndDate()))||!LocalTime.parse(r.getTime()).isBefore(LocalTime.now())||history.hasToday(r.getId()))continue;if("WEEKLY".equals(r.getFrequency())&& (r.getDaysOfWeek()==null||!r.getDaysOfWeek().contains(day)))continue;MedicineHistory h=new MedicineHistory();h.setReminder(r);h.setStatus("MISSED");history.log(r.getId(),"MISSED",r.getMedicine().getProfile().getUser().getId());}}
}
